13:public class People {
42:    public People(JdbcTemplate jdbc, net.officefloor.hq.app.sheet.Sheets sheets) {
120:    public List<Person> list(String sheetId) {
126:    public int move(Person person, boolean up) {
157:    public List<String> tree(String sheetId) {
205:    public boolean wouldClash(Person person, String name) {
220:    public boolean nameUsedInTree(String sheetId, String name, Person except) {
268:    public void addAlias(Person person, String alias) {
276:    public void addPatron(Person person, Person patron) {
289:    public void merge(Person from, Person into) {
345:    public Person transferIn(Person from, String toSheet) {
366:    public void transferOut(Person person) {
384:    public String originOf(String sheetId, String name) {
391:    public List<Person> mergedAfter(String sheetId, java.time.LocalDate date) {
396:    public Person find(String sheetId, long id) {
402:    public Person findByName(String sheetId, String name) {
415:    public boolean nameTaken(String sheetId, String name, Long exceptId) {
420:    public boolean nameTaken(String sheetId, String name, Long exceptId, Person exceptInTree) {
432:    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
440:    public Person add(String sheetId, String name, String grade) {
445:    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
475:    public void saveStatement(Person person) {
483:    public void addStatement(Person person) {
491:    public void cancelStatement(Person person) {
